<?php require_once __DIR__.'/../includes/bootstrap.php';require_role('petugas');$uid=(int)current_user()['id_user'];$q=$pdo->prepare('SELECT k.*,u.username FROM kegiatan k JOIN users u ON u.id_kegiatan=k.id_kegiatan WHERE u.id_user=? AND u.role_user=\'petugas\'');$q->execute([$uid]);$k=$q->fetch();if(!$k){http_response_code(403);exit('Akun petugas tidak terhubung dengan kegiatan.');}$s=$pdo->prepare('SELECT id_petugas,nama_petugas,kecamatan FROM petugas WHERE id_user=? AND id_kegiatan=? AND deleted_at IS NULL ORDER BY nama_petugas');$s->execute([$uid,$k['id_kegiatan']]);$list=$s->fetchAll();page_header('Dashboard Petugas');?><div class="card p-4 mb-3"><div class="d-flex justify-content-between flex-wrap"><div><div class="muted-label">Kegiatan yang dikelola</div><h2 class="h4 fw-bold"><?=e($k['nama_kegiatan'])?></h2><div class="text-secondary"><?=e($k['nomor_kegiatan'])?></div></div><span class="badge text-bg-<?=$k['status']==='aktif'?'success':'secondary'?> align-self-start"><?=e(ucfirst($k['status']))?></span></div><div class="row mt-3"><div class="col-md-4"><div class="muted-label">Periode</div><?=format_tanggal($k['tanggal_mulai'])?> – <?=format_tanggal($k['tanggal_selesai'])?></div><div class="col-md-4"><div class="muted-label">Tujuan Akhir</div><?=e(tujuan_label($k['tujuan_akhir']))?></div><div class="col-md-4"><div class="muted-label">Status Input</div><?=$k['status']==='aktif'?'Input diizinkan':'Kegiatan nonaktif — hanya melihat data lama'?></div></div></div><div class="card p-4"><h2 class="h5 fw-bold">Pilih Identitas Petugas</h2><p class="small text-secondary">Satu akun dapat digunakan bersama. Pilih identitas yang sesuai sebelum masuk ke pengelolaan progress.</p><div class="table-responsive"><table class="table"><thead><tr><th>No</th><th>Nama Petugas</th><th>Kecamatan</th><th>Aksi</th></tr></thead><tbody><?php foreach($list as $i=>$p):?><tr><td><?=$i+1?></td><td><?=e($p['nama_petugas'])?></td><td><?=e($p['kecamatan'])?></td><td><form method="post" action="<?=APP_BASE_URL?>/petugas/select.php"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="petugas_id" value="<?=$p['id_petugas']?>"><button class="btn btn-sm btn-outline-primary">Pilih dan Kelola Progress</button></form></td></tr><?php endforeach;?><?php if(!$list):?><tr><td colspan="4" class="text-center text-secondary">Belum ada identitas petugas yang didaftarkan admin.</td></tr><?php endif;?></tbody></table></div></div><?php page_footer();?>
